import {AnatomyViewer} from './viewer.js?v=legacy-studio-1';
import {SYSTEMS} from './explosion.js';
import {matchesPart,locationLabel,KIND_LABELS} from './part-info.js';
import {PartLabels} from './labels.js';
import {newViewState,enterAssembly,enterSystem,revealPart,toggleVisibility,restoreView} from './assemblies.js';
const $=id=>document.getElementById(id),nf=new Intl.NumberFormat('zh-CN');
const state=newViewState();
let viewer,manifest,partCatalog,labels,assemblyIndex,catalogMode='groups',limit=70,playFrame=0,noticeTimer=0,fitTimer=0;
const systemsById=new Map(SYSTEMS.map(s=>[s.id,s]));
const controls=['reset','fit-view','back-all','explode','assemble','explode-all','play-explosion','level-groups','level-parts','group-intact','group-breakdown'];
function notice(message){$('status-message').textContent=message;$('status-message').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('status-message').classList.remove('show'),2800)}
function ready(){return !!viewer?.ready}
function renderSystems(){const container=$('system-list');container.replaceChildren();for(const s of SYSTEMS){const row=document.createElement('div');row.className='system-row'+(state.system===s.id?' active':'');const b=document.createElement('button');b.className='system-select';b.dataset.system=s.id;b.setAttribute('aria-pressed',String(state.system===s.id));const count=manifest?manifest.parts.filter(p=>s.id==='all'||p.system===s.id).length:null;
 const code=document.createElement('span');code.className='system-symbol';code.textContent=s.code;const name=document.createElement('span');name.className='system-name';name.textContent=s.label;const number=document.createElement('span');number.className='system-count';number.textContent=count===null?'—':nf.format(count);b.append(code,name,number);b.disabled=!ready();b.onclick=()=>chooseSystem(s.id);row.append(b);
 if(s.id!=='all'){const eye=document.createElement('button');eye.className='system-eye'+(state.hiddenSystems.has(s.id)?' off':'');eye.textContent=state.hiddenSystems.has(s.id)?'○':'◉';eye.title=(state.hiddenSystems.has(s.id)?'显示':'隐藏')+s.label;eye.setAttribute('aria-label',eye.title);eye.setAttribute('aria-pressed',String(!state.hiddenSystems.has(s.id)));eye.disabled=!ready();eye.onclick=()=>{toggleVisibility(state,'systems',s.id,assemblyIndex);if(!state.selected)selectPart(null);sync();refreshCatalog();viewer.fit()};row.append(eye)}container.append(row);}}
function renderGroups(){
 const list=$('group-catalog');list.replaceChildren();
 if(!assemblyIndex){const p=document.createElement('p');p.className='empty-list';p.textContent='正在整理功能总成…';list.append(p);return;}
 const overview=document.createElement('button');overview.className='group-overview';overview.textContent='↗ 整车总览 · 13 个总成';overview.onclick=showOverview;list.append(overview);
 for(const group of assemblyIndex.groups){
  const row=document.createElement('div');row.className='assembly-card'+(state.assembly===group.id?' active':'');row.style.setProperty('--group-color',group.color);
  const button=document.createElement('button');button.className='assembly-card-main';button.dataset.assembly=group.id;button.setAttribute('aria-pressed',String(state.assembly===group.id));
  const title=document.createElement('strong');title.textContent=group.label;const count=document.createElement('span');count.textContent=`${nf.format(group.partIds.length)} 个部件`;
  const note=document.createElement('small');note.textContent=group.description;button.append(title,count,note);button.onclick=()=>chooseAssembly(group.id);
  const eye=document.createElement('button');eye.className='assembly-eye';eye.textContent=state.hiddenAssemblies.has(group.id)?'○':'◉';eye.title=(state.hiddenAssemblies.has(group.id)?'显示':'隐藏')+group.label;eye.setAttribute('aria-label',eye.title);eye.setAttribute('aria-pressed',String(!state.hiddenAssemblies.has(group.id)));
  eye.onclick=()=>{toggleVisibility(state,'assemblies',group.id,assemblyIndex);if(!state.selected)selectPart(null);sync();refreshCatalog();viewer.fit();};
  row.append(button,eye);list.append(row);
 }
}
function showCatalog(mode){catalogMode=mode;const groups=mode==='groups';$('group-catalog').hidden=!groups;$('parts-catalog').hidden=groups;for(const [id,active] of [['tab-groups',groups],['tab-parts',!groups]]){$(id).setAttribute('aria-selected',String(active));$(id).tabIndex=active?0:-1;}}
function renderGroupSummary(){const group=assemblyIndex?.byId.get(state.assembly);$('group-summary').hidden=!group;$('system-list').hidden=!!group;if(!group)return;$('group-name').textContent=`${group.label} · ${nf.format(group.partIds.length)}`;$('group-description').textContent=group.description;$('group-operation').textContent=group.operation;$('group-hint').textContent=group.inspectionHint;}
function refreshCatalog(){renderSystems();renderGroups();renderGroupSummary();renderAssemblies();renderList();showCatalog(catalogMode);}
function clearSelection(){selectPart(null);viewer.select(null);}
function chooseAssembly(id){if(!ready()||!assemblyIndex.byId.has(id))return;stopPlay();clearTimeout(fitTimer);enterAssembly(state,id,assemblyIndex);catalogMode='parts';$('search').value='';$('assembly-filter').value='all';limit=70;clearSelection();sync();refreshCatalog();viewer.fit();closeMobile();}
function showOverview(){if(!ready())return;stopPlay();clearTimeout(fitTimer);state.assembly=null;state.system='all';state.explodeMode='groups';state.amount=0;state.isolated=null;state.hiddenSystems.clear();catalogMode='groups';clearSelection();sync();refreshCatalog();viewer.fit();closeMobile();}
function setLevel(mode){if(!ready()||!['groups','parts'].includes(mode))return;if(mode==='groups'){showOverview();return;}stopPlay();clearTimeout(fitTimer);state.explodeMode='parts';state.amount=0;catalogMode='parts';sync();refreshCatalog();viewer.fit();}
function handleModelPick(id){if(id&&state.explodeMode==='groups'&&!state.assembly)chooseAssembly(assemblyIndex.byPart.get(id).id);else selectPart(id);}
function filteredParts(){if(!manifest)return [];const q=$('search').value,assembly=$('assembly-filter').value;return manifest.parts.filter(p=>(state.system==='all'||p.system===state.system)&&(!state.assembly||assemblyIndex.byPart.get(p.id).id===state.assembly)&&(assembly==='all'||p.assemblyGroup===assembly)&&matchesPart(p,q))}
function renderAssemblies(){const select=$('assembly-filter'),previous=select.value;select.replaceChildren(new Option('全部装配分组','all'));if(!manifest)return;const groups=new Map();for(const p of manifest.parts){if((state.system!=='all'&&p.system!==state.system)||(state.assembly&&assemblyIndex.byPart.get(p.id).id!==state.assembly))continue;const group=groups.get(p.assemblyGroup)||{label:p.assemblyLabel,count:0};group.count++;groups.set(p.assemblyGroup,group)}for(const [id,g] of groups)select.add(new Option(`${g.label} · ${g.count}`,id));select.value=groups.has(previous)?previous:'all';}
function openPart(id,{revealInCatalog=false}={}){const p=viewer?.parts.get(id);if(!p)return;stopPlay();clearTimeout(fitTimer);revealPart(state,id,assemblyIndex);catalogMode='parts';if(revealInCatalog){$('search').value='';$('assembly-filter').value='all';limit=70;}sync();refreshCatalog();selectPart(id);viewer.focusPart(id);closeMobile();}

function renderList(){const list=$('part-list');list.replaceChildren();if(!manifest){$('list-count').textContent='—';const hint=document.createElement('p');hint.className='empty-list';hint.textContent='正在载入零件目录…';list.append(hint);return;}const parts=filteredParts();$('list-count').textContent=nf.format(parts.length);for(const p of parts.slice(0,limit)){const button=document.createElement('button');button.className='part-row'+(state.selected===p.id?' selected':'');button.dataset.part=p.id;button.title=p.info?.purpose||p.label;const title=document.createElement('strong');title.textContent=p.label;title.title=p.label;const sub=document.createElement('small');sub.textContent=`${p.id.toUpperCase()} · ${p.assemblyLabel||p.subsystem}`;const purpose=document.createElement('em');purpose.textContent=p.info?.purpose||'';button.append(title,sub,purpose);button.onclick=()=>openPart(p.id);list.append(button)}if(!parts.length){const empty=document.createElement('p');empty.className='empty-list';empty.textContent='没有找到对应零件。试试其他名称，或返回整车目录。';list.append(empty)}if(parts.length>limit){const more=document.createElement('button');more.className='load-more';more.textContent=`显示更多 · 还有 ${nf.format(parts.length-limit)} 个`;more.onclick=()=>{const top=list.scrollTop;limit+=70;renderList();list.scrollTop=top};list.append(more)}}
function closeMobile(){$('catalog').classList.remove('open');$('mobile-catalog').setAttribute('aria-expanded','false')}
function chooseSystem(id){if(!ready()||!systemsById.has(id))return;stopPlay();clearTimeout(fitTimer);enterSystem(state,id,assemblyIndex);catalogMode='parts';$('search').value='';$('assembly-filter').value='all';limit=70;clearSelection();sync();refreshCatalog();viewer.fit();closeMobile();}

function sync(){
 if(!viewer)return;viewer.update(state);const system=systemsById.get(state.system),group=assemblyIndex?.byId.get(state.assembly),groupMode=state.explodeMode==='groups';
 $('crumb-system').textContent=group?`/ ${group.shortLabel||group.label}`:state.system==='all'?'':`/ ${system.short}`;
 $('stage-mode').textContent=state.isolated?'PART STUDY':group?'ASSEMBLY STUDY':groupMode?'FUNCTIONAL ASSEMBLIES':state.amount>.01?'EXPLODED VIEW':'ASSEMBLED';
 $('stage-title').textContent=state.isolated?'零件独立查看':group?group.label:groupMode?(state.amount>.01?'总成分开，结构完整。':'从整车，看见每个总成。'):state.system==='all'?'完整的 Corvair':system.label;
 $('stage-description').textContent=state.isolated?'旋转、缩放，检查这个零件的每个角度':group?'组内展开 · 点击部件查看用途':groupMode?'点击总成进入组内 · 同组部件一起移动':system.description;
 $('assembly-label').textContent=group?`${group.shortLabel||group.label} · 组内`:'装配状态';
 $('level-groups').setAttribute('aria-pressed',String(groupMode));$('level-parts').setAttribute('aria-pressed',String(!groupMode));
 $('explode').value=Math.round(state.amount*100);$('explode').style.setProperty('--progress',`${state.amount*100}%`);
 $('explode-output').replaceChildren(document.createTextNode(String(Math.round(state.amount*100))),Object.assign(document.createElement('span'),{textContent:'% 展开'}));
 $('visible-count').textContent=`${nf.format(viewer.visibleCount||0)} / ${nf.format(group?.partIds.length||manifest?.parts.filter(p=>state.system==='all'||p.system===state.system).length||0)} ${group?'个组内部件':'个部件'}`;
 const hidden=state.hidden.size+state.hiddenSystems.size+state.hiddenAssemblies.size;
 $('restore-hidden').hidden=!hidden&&!state.isolated;$('restore-hidden').textContent=state.isolated?(group?'← 返回总成':'← 返回系统视图'):`恢复隐藏内容（${hidden}）`;
 $('isolate-part').textContent=state.isolated?(group?'返回总成':'返回系统'):'单独查看';viewer.setInspectionFraming($('inspector'));labels?.update(state);
}

function selectPart(id){
 if(!ready())return;const p=viewer.parts.get(id);state.selected=p?.id||null;viewer.select(state.selected);$('inspector').hidden=!p;$('stage').classList.toggle('has-selection',!!p);viewer.setInspectionFraming($('inspector'));
 document.querySelectorAll('.part-row.selected').forEach(el=>el.classList.remove('selected'));
 if(!p){labels?.update(state);return;}
 document.querySelector(`.part-row[data-part="${p.id}"]`)?.classList.add('selected');
 $('selected-id').textContent=p.id.toUpperCase();$('selected-name').textContent=p.label;
 $('selected-system').textContent=`${systemsById.get(p.system)?.short||p.system} / ${p.assemblyLabel||p.subsystem}`;const group=assemblyIndex.byPart.get(p.id);$('inspect-assembly').textContent=`↗ 查看所属总成：${group.label}`;$('inspect-assembly').onclick=()=>chooseAssembly(group.id);
 const info=p.info;
 $('selected-purpose').textContent=info.purpose;$('selected-operation').textContent=info.operation;$('selected-tip').textContent=info.inspectTip;
 $('selected-location').textContent=locationLabel(p);$('selected-materials').textContent=info.materials.join(' / ');
 $('selected-tags').replaceChildren();
 for(const name of [KIND_LABELS[info.kind],p.internal?'内部组件':null,info.familyCount>1?`同类对象 ${nf.format(info.familyCount)} 件`:null].filter(Boolean)){const tag=document.createElement('span');tag.textContent=name;$('selected-tags').append(tag)}
 $('related-parts').replaceChildren();
 for(const id of info.relatedIds){const related=viewer.parts.get(id);if(!related)continue;const button=document.createElement('button');const title=document.createElement('strong');title.textContent=related.label;const sub=document.createElement('span');sub.textContent=`${related.id.toUpperCase()} · ${related.assemblyLabel}`;button.append(title,sub);button.title=related.info.purpose;button.onclick=()=>openPart(id,{revealInCatalog:true});$('related-parts').append(button)}
 if(!$('related-parts').childElementCount){const note=document.createElement('p');note.className='related-empty';note.textContent='可在左侧装配分组中查看同组零件。';$('related-parts').append(note)}
 $('selected-source').textContent=p.sourceName;const dims=p.bounds.max.map((v,i)=>(v-p.bounds.min[i])*1000);
 $('selected-size').textContent=dims.map(v=>v<10?v.toFixed(1):Math.round(v)).join(' × ')+' mm';
 $('selected-references').replaceChildren();
 for(const id of info.sourceIds){const source=partCatalog.sources[id],row=document.createElement('p');row.className='reference-item';if(source.url){const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title;row.append(a)}else row.textContent=source.title;if(source.note){const note=document.createElement('small');note.textContent=source.note;row.append(note)}$('selected-references').append(row)}
 $('source-details').open=false;$('inspector').scrollTop=0;$('isolate-part').textContent=state.isolated?(state.assembly?'返回总成':'返回系统'):'单独查看';viewer.setInspectionFraming($('inspector'));labels?.update(state);
}

function setExplosion(value,autoFit=true){if(!ready())return;state.amount=Math.max(0,Math.min(1,Number(value)));sync();clearTimeout(fitTimer);if(autoFit)fitTimer=setTimeout(()=>viewer.fit(),180)}
function reset(){if(!ready())return;stopPlay();clearTimeout(fitTimer);Object.assign(state,newViewState());catalogMode='groups';$('search').value='';$('assembly-filter').value='all';limit=70;clearSelection();sync();refreshCatalog();viewer.fit('perspective');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='perspective'));closeMobile();}

function stopPlay(){cancelAnimationFrame(playFrame);playFrame=0;$('play-explosion').innerHTML='<span aria-hidden="true">▷</span> 演示拆解'}
function play(){if(!ready())return;if(playFrame){stopPlay();return}const start=performance.now(),from=state.amount,direction=from>.9?-1:1;$('play-explosion').innerHTML='<span aria-hidden="true">Ⅱ</span> 暂停演示';const target=direction===1?1:0;state.amount=target;viewer.update(state);viewer.fit();state.amount=from;viewer.update(state);function tick(now){const t=Math.min(1,(now-start)/6500),ease=t*t*(3-2*t);setExplosion(from+(target-from)*ease,false);if(t<1)playFrame=requestAnimationFrame(tick);else{stopPlay();viewer.fit()}}playFrame=requestAnimationFrame(tick)}
$('explode').addEventListener('input',e=>{stopPlay();setExplosion(Number(e.target.value)/100)});$('assemble').onclick=()=>{stopPlay();setExplosion(0)};$('explode-all').onclick=()=>{stopPlay();setExplosion(1)};$('play-explosion').onclick=play;$('reset').onclick=reset;$('back-all').onclick=showOverview;$('fit-view').onclick=()=>viewer?.fit();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(!ready())return;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));viewer.fit(b.dataset.view)});
$('search').addEventListener('input',()=>{limit=70;renderList()});$('assembly-filter').addEventListener('change',()=>{limit=70;renderList()});$('toggle-labels').onclick=()=>{if(!labels)return;labels.setEnabled(!labels.enabled);$('toggle-labels').setAttribute('aria-pressed',String(labels.enabled));$('toggle-labels').classList.toggle('active',labels.enabled)};$('close-inspector').onclick=()=>selectPart(null);$('focus-part').onclick=()=>viewer.focusPart(state.selected);$('isolate-part').onclick=()=>{if(!state.selected)return;state.isolated=state.isolated?null:state.selected;sync();viewer.fit();notice(state.isolated?'已单独显示所选零件':state.assembly?'已返回总成':'已返回系统视图')};$('hide-part').onclick=()=>{if(!state.selected)return;const id=state.selected;state.hidden.add(id);state.isolated=null;selectPart(null);sync();notice('零件已隐藏，可随时恢复')};$('restore-hidden').onclick=()=>{restoreView(state);sync();refreshCatalog();viewer.fit()};$('mobile-catalog').onclick=()=>{const opened=$('catalog').classList.toggle('open');$('mobile-catalog').setAttribute('aria-expanded',String(opened))};$('help-toggle').onclick=()=>{const opened=$('help-panel').hidden;$('help-panel').hidden=!opened;$('help-toggle').setAttribute('aria-expanded',String(opened))};
$('tab-groups').onclick=()=>{renderGroups();showCatalog('groups')};$('tab-parts').onclick=()=>showCatalog('parts');
for(const id of ['tab-groups','tab-parts'])$(id).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const target=(e.key==='Home'||(e.key!=='End'&&id==='tab-parts'))?'tab-groups':'tab-parts';$(target).click();$(target).focus()});
$('back-groups').onclick=()=>{renderGroups();showCatalog('groups')};$('group-intact').onclick=()=>{stopPlay();state.isolated=null;sync();setExplosion(0);viewer.fit()};$('group-breakdown').onclick=()=>{stopPlay();state.isolated=null;state.explodeMode='parts';sync();setExplosion(1);viewer.fit()};
$('level-groups').onclick=()=>setLevel('groups');$('level-parts').onclick=()=>setLevel('parts');
window.addEventListener('keydown',e=>{if((e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement||e.target instanceof HTMLTextArea)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){selectPart(null);closeMobile();$('help-panel').hidden=true;$('help-toggle').setAttribute('aria-expanded','false')}if(e.key.toLowerCase()==='f'&&state.selected){e.preventDefault();viewer.focusPart(state.selected)}if(e.key.toLowerCase()==='r'){e.preventDefault();reset()}});
function showError(message){if(window.parent!==window)window.parent.postMessage({type:'corvair-error'},location.origin);$('loading').hidden=false;$('loading-title').textContent='模型暂时无法打开';$('loading-detail').textContent=message;$('retry').hidden=false;$('loading-progress').hidden=true;document.querySelector('.loading-spinner').style.display='none';$('retry').onclick=()=>location.reload();}
window.addEventListener('viewererror',e=>showError(e.detail));
renderSystems();renderGroups();renderList();showCatalog(catalogMode);controls.forEach(id=>$(id).disabled=true);
try{
 viewer=new AnatomyViewer($('viewport'),handleModelPick);viewer.beforeFocus=()=>{clearTimeout(fitTimer);stopPlay()};viewer.beforeCameraInteraction=()=>{clearTimeout(fitTimer);stopPlay();document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'))};
 const [response,groupResponse]=await Promise.all([fetch('./assets/part-info.json'),fetch('./assets/assemblies.json')]);if(!response.ok||!groupResponse.ok)throw Error('无法载入零件或总成目录，请刷新重试。');partCatalog=await response.json();const assemblyCatalog=await groupResponse.json();
 manifest=await viewer.load('./assets/manifest.json',(progress,system)=>{$('loading-progress').value=Math.min(100,progress*100);$('loading-detail').textContent=`${systemsById.get(system)?.label||'零件目录'} · ${Math.round(progress*100)}%`},partCatalog,assemblyCatalog);
 assemblyIndex=viewer.assemblyIndex;for(const p of manifest.parts){const group=assemblyIndex.byPart.get(p.id);p.searchText+=' '+group.label+' '+group.shortLabel;}
 labels=new PartLabels(viewer,$('part-labels'),id=>openPart(id,{revealInCatalog:true}),chooseAssembly);viewer.onDraw=()=>labels.draw();
 new ResizeObserver(()=>{viewer.setInspectionFraming($('inspector'));labels.draw()}).observe($('inspector'));
 window.corvair={
  getState:()=>({...viewer.getDiagnostics(),hiddenParts:[...state.hidden],hiddenSystems:[...state.hiddenSystems],hiddenAssemblies:[...state.hiddenAssemblies],annotations:labels.enabled,annotationCount:Object.keys(partCatalog.entries).length}),
  getParts:(query='')=>manifest.parts.filter(p=>matchesPart(p,query)).map(p=>({id:p.id,label:p.label,system:p.system,subsystem:p.subsystem,internal:p.internal,purpose:p.info.purpose})),
  getPartInfo:id=>{const p=viewer.parts.get(id);return p?{id:p.id,label:p.label,sourceName:p.sourceName,assemblyId:assemblyIndex.byPart.get(id).id,assemblyLabel:assemblyIndex.byPart.get(id).label,location:locationLabel(p),...p.info}:null},
  getAssemblies:()=>assemblyIndex.groups.map(g=>({id:g.id,label:g.label,count:g.partIds.length,description:g.description,partIds:g.partIds})),
  setExplosion,chooseSystem,chooseAssembly,setLevel,selectPart:id=>id?openPart(id,{revealInCatalog:true}):selectPart(null),reset
 };
 $('loading').hidden=true;controls.forEach(id=>$(id).disabled=false);refreshCatalog();sync();registerTools();
 const initialAssembly=new URLSearchParams(location.search).get('assembly');if(initialAssembly&&assemblyIndex.byId.has(initialAssembly))chooseAssembly(initialAssembly);
 if(window.parent!==window)window.parent.postMessage({type:'corvair-ready'},location.origin);
}catch(error){console.error(error);showError(error.message||'请检查本地文件是否完整，然后重试。')}

function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(e=>console.warn('WebMCP',e))}catch(e){console.warn('WebMCP',e)}};
 register({name:'inspect_corvair',title:'查看 Corvair 状态与零件',description:'Read the current anatomy view, search parts by name, ID or function, and read selected part purpose and operation.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input.query!==undefined&&typeof input.query!=='string')throw Error('query must be a string');return {state:window.corvair.getState(),parts:window.corvair.getParts(input.query||'').slice(0,60),selectedPart:window.corvair.getPartInfo(state.selected),assemblies:window.corvair.getAssemblies().map(({partIds,...g})=>g)}}});
 register({name:'set_corvair_view',title:'展开或合拢汽车',description:'Show a whole-car assembly overview, inspect a functional assembly such as steering or brakes, or select a component. Group overview keeps each assembly rigid; assembly inspection expands its parts. Incompatible contexts are rejected before any state changes.',inputSchema:{type:'object',properties:{system:{type:'string',enum:SYSTEMS.map(s=>s.id)},assemblyId:{type:'string'},level:{type:'string',enum:['groups','parts']},explosion:{type:'number',minimum:0,maximum:1},partId:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(input.assemblyId!==undefined&&!assemblyIndex.byId.has(input.assemblyId))throw Error('Unknown assembly');if(input.level!==undefined&&!['groups','parts'].includes(input.level))throw Error('Unknown level');if(input.assemblyId&&input.system&&input.system!=='all')throw Error('Choose an assembly or a system');if(input.assemblyId&&input.level==='groups')throw Error('Assembly inspection uses part level');if(input.level==='groups'&&input.system&&input.system!=='all')throw Error('Group overview uses the whole car');if(input.level==='groups'&&input.partId)throw Error('Part inspection uses part level');if(input.system&&input.system!=='all'&&input.partId&&viewer.parts.get(input.partId)?.system!==input.system)throw Error('Part is outside system');if(input.assemblyId&&input.partId&&assemblyIndex.byPart.get(input.partId)?.id!==input.assemblyId)throw Error('Part is outside assembly');if(input.system!==undefined&&!systemsById.has(input.system))throw Error('Unknown system');if(input.explosion!==undefined&&(!Number.isFinite(input.explosion)||input.explosion<0||input.explosion>1))throw Error('explosion must be between 0 and 1');if(input.partId!==undefined&&!viewer.parts.has(input.partId))throw Error('Unknown part');if(input.system)chooseSystem(input.system);if(input.level)setLevel(input.level);if(input.assemblyId)chooseAssembly(input.assemblyId);if(input.partId)openPart(input.partId,{revealInCatalog:true});if(input.explosion!==undefined)setExplosion(input.explosion,!input.partId);if(input.partId)viewer.focusPart(input.partId);await new Promise(r=>setTimeout(r,650));viewer.settle();return window.corvair.getState();}});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}

